        <?php if (!$registration['participants']): ?><div class="text-center opacity-60 py-4"><?= $isCancelled && $participantHistory ? 'Tidak ada peserta aktif. Riwayat peserta tersedia di bawah.' : 'Belum ada peserta.' ?></div><?php endif; ?>
