                    <?php if ($historyCommitted > 0): ?><p class="font-10 color-yellow-dark mb-0 mt-2"><i class="fa fa-money-bill-wave me-1"></i>Komitmen tersimpan: <?= rupiah(simp_money_from_cents($historyCommitted)) ?></p><?php endif; ?>
